def has_triple(A, n):
    # A is a set of integers
    # x, y, z are in A. We need distinct a, b, c in {1, ..., n}
    # such that x = a+b, y = b+c, z = c+a.
    # This is equivalent to:
    # x+y+z is even, and x+y > z, x+z > y, y+z > x
    # and x, y, z are distinct, and a, b, c = (x+z-y)/2, (x+y-z)/2, (y+z-x)/2 are in {1, ..., n}.
    # Let's precalculate all possible triples (x, y, z) in {1, ..., n} that satisfy this.
