def get_all_triples(n):
    triples = []
    for x in range(1, n + 1):
        for y in range(x + 1, n + 1):
            for z in range(y + 1, n + 1):
                if (x + y + z) % 2 == 0:
                    a = (x - y + z) // 2
                    b = (x + y - z) // 2
                    c = (-x + y + z) // 2
                    if a >= 1 and b >= 1 and c >= 1:
                        # a, b, c are already <= n because x, y, z <= n
                        # and a+b = x <= n etc.
                        # Check if a, b, c are distinct
                        if len({a, b, c}) == 3:
                            triples.append({x, y, z})
    return triples

def find_max_A_fast(n):
    triples = get_all_triples(n)
    # Now we want to find the largest A subset of {1, ..., n} that contains no triple.
    # This is the Maximum Independent Set problem on a hypergraph.
    # For small n, we can use backtracking.

    import itertools

    # To speed up, we can only consider elements that are part of at least one triple.
    elements_in_triples = set()
    for t in triples:
        elements_in_triples.update(t)

    other_elements = set(range(1, n + 1)) - elements_in_triples

    # Now find max A' subset of elements_in_triples with no triple.
    nodes = sorted(list(elements_in_triples))
    num_nodes = len(nodes)

    best_size = 0

    def solve(index, current_A):
        nonlocal best_size
        if index == num_nodes:
            best_size = max(best_size, len(current_A))
            return

        # Pruning
        if len(current_A) + (num_nodes - index) <= best_size:
            return

        # Try including nodes[index]
        node = nodes[index]
        can_add = True
        for t in triples:
            if node in t:
                if t.issubset(current_A | {node}):
                    can_add = False
                    break
        if can_add:
            solve(index + 1, current_A | {node})

        # Try excluding nodes[index]
        solve(index + 1, current_A)

    solve(0, set())
    return best_size + len(other_elements)

for n in range(6, 21):
    print(f"n={n}, max_size={find_max_A_fast(n)}")
